{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://mdbase.dev/contracts/schemas/mdbase.comment/1.0.0.schema.json",
  "title": "Comment",
  "description": "A comment, reply or suggested edit on a Markdown record, stored as its own record. The comment's Markdown body is its text.",
  "type": "object",
  "required": [
    "document",
    "created_at"
  ],
  "properties": {
    "document": {
      "type": "string",
      "pattern": "\\S",
      "description": "Link to the commented record, such as [[chapters/method]]. Replies repeat their thread's document so one query finds a record's whole discussion."
    },
    "in_reply_to": {
      "type": "string",
      "pattern": "\\S",
      "description": "Link to the first comment of the thread this comment replies to. Absent on the first comment of a thread."
    },
    "motivation": {
      "enum": [
        "commenting",
        "replying",
        "editing"
      ],
      "default": "commenting",
      "description": "commenting starts a thread, replying answers one, and editing suggests replacing the target's text."
    },
    "target": {
      "type": "object",
      "description": "Where in the document the thread is anchored. Absent means the whole record. Only the first comment of a thread has a target.",
      "properties": {
        "quote": {
          "type": "object",
          "description": "The anchored text and the text around it. The quote is authoritative; positions are a hint.",
          "required": [
            "exact"
          ],
          "properties": {
            "exact": {
              "type": "string",
              "description": "The anchored text exactly as it appears in the record body. Empty for an insertion point, which prefix or suffix then locates."
            },
            "prefix": {
              "type": "string",
              "description": "Text immediately before exact, to tell repeated occurrences apart."
            },
            "suffix": {
              "type": "string",
              "description": "Text immediately after exact, to tell repeated occurrences apart."
            }
          },
          "if": {
            "required": [
              "exact"
            ],
            "properties": {
              "exact": {
                "type": "string",
                "maxLength": 0
              }
            }
          },
          "then": {
            "anyOf": [
              {
                "required": [
                  "prefix"
                ],
                "properties": {
                  "prefix": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              {
                "required": [
                  "suffix"
                ],
                "properties": {
                  "suffix": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              }
            ]
          },
          "additionalProperties": false
        },
        "text_position": {
          "type": "object",
          "description": "Offsets of the quote in one revision of the record body.",
          "required": [
            "basis",
            "unit",
            "start",
            "end"
          ],
          "properties": {
            "basis": {
              "type": "object",
              "required": [
                "profile",
                "hash"
              ],
              "properties": {
                "profile": {
                  "const": "markdown-body",
                  "description": "Offsets count the record's Markdown body as stored, after the frontmatter, so frontmatter edits never move them."
                },
                "hash": {
                  "type": "string",
                  "pattern": "^sha256:[0-9a-f]{64}$",
                  "description": "SHA-256 of the UTF-8 body the offsets were measured in."
                }
              },
              "additionalProperties": false
            },
            "unit": {
              "const": "unicode_code_point"
            },
            "start": {
              "type": "integer",
              "minimum": 0
            },
            "end": {
              "type": "integer",
              "minimum": 0
            }
          },
          "additionalProperties": false
        }
      },
      "required": [
        "quote"
      ],
      "additionalProperties": false
    },
    "suggestion": {
      "type": "object",
      "description": "The suggested edit of an editing comment: replace the target's quote with replacement.",
      "required": [
        "replacement"
      ],
      "properties": {
        "replacement": {
          "type": "string",
          "description": "The text to put in place of the quote. Empty suggests deleting it."
        },
        "outcome": {
          "enum": [
            "accepted",
            "rejected"
          ],
          "description": "What happened to the suggestion once its thread was resolved."
        }
      },
      "additionalProperties": false
    },
    "status": {
      "enum": [
        "open",
        "resolved"
      ],
      "default": "open",
      "description": "Whether the thread is still open. Only meaningful on the first comment of a thread."
    },
    "resolved_by": {
      "type": "string",
      "pattern": "\\S",
      "description": "Link to the mdbase.person record of who resolved the thread."
    },
    "resolved_at": {
      "type": "string",
      "format": "date-time"
    },
    "created_by": {
      "type": "string",
      "pattern": "\\S",
      "description": "Link to the mdbase.person record of the comment's author. Absent when the author has no person record."
    },
    "created_at": {
      "type": "string",
      "format": "date-time"
    },
    "modified_at": {
      "type": "string",
      "format": "date-time"
    },
    "deleted_at": {
      "type": "string",
      "format": "date-time",
      "description": "When the comment was withdrawn. The record stays so its thread and replies keep their shape; its body should be emptied."
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "motivation": {
            "const": "editing"
          }
        },
        "required": [
          "motivation"
        ]
      },
      "then": {
        "required": [
          "target",
          "suggestion"
        ],
        "properties": {
          "target": {
            "type": "object"
          },
          "suggestion": {
            "type": "object"
          }
        }
      }
    }
  ],
  "additionalProperties": false
}
